procedure HardwareRefunds {
  about "Refund a return immediately"
  policy HardwarePolicy
  sheet Returns "Returns" { return_no: Text, customer: Text, phone: Phone, amount: Money, bought: Date, opened: Bool, status: Text }
  trigger when new row r in Returns

  if r.amount > $100.00 {
    notify owner "Refund of {r.amount} for return {r.return_no} would be over the $100 limit."
    stop "over the limit"
  }
  if r.amount <= $20.00 {
    refund r.amount for r.return_no reason "refund request"
  } else {
    refund r.amount for r.return_no reason "refund request", ask owner first timeout 1 day else stop "refund not approved"
  }
  update r set status = "refunded"
}
```

