procedure LaundryReorder {
  about "Reorder supplies below their minimum"
  policy LaundryPolicy
  sheet Supplies "Supplies" { item: Text, on_hand: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every day at 06:00

  let all = fetch Supplies
  let low = filter all where on_hand < minimum
  for each i in low up to 3 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $80.00 {
      notify owner "Reorder of {i.item} would be {cost}, over the $80 limit."
      skip
    }
    order "{i.reorder_qty} x {i.item}" from i.supplier cost cost, ask owner first timeout 1 day else skip
    log "ordered {i.item}"
  }
}
```

