procedure IceRefunds {
  about "Handle refund deposits within limits"
  policy IcePolicy
  sheet PartyCancellations "PartyCancellations" { ref: Text, host: Text, phone: Phone, deposit: Money, party_on: Date }
  trigger when new row r in PartyCancellations

  if r.party_on < today() + 3 days {
    notify owner "Short-notice refund deposit for {r.host} is {r.deposit}. Please handle it."
    stop "short notice refund goes to owner"
  }
  if r.deposit > $100.00 {
    notify owner "Refund deposit for {r.host} is {r.deposit}, over $100. Please handle it."
    stop "over $100 refund goes to owner"
  }
  if r.deposit <= $40.00 {
    refund r.deposit for r.ref reason "refund deposit"
  } else {
    refund r.deposit for r.ref reason "refund deposit", ask owner first timeout 1 day else stop "refund not approved"
  }
  let m = draft sms to r.phone: "Hi {r.host default 'there'}, your refund of {r.deposit} is coming back."
  let ok = request approval of m from owner timeout 1 day else stop "message not approved"
  send ok
}
```

