procedure RepairReorder {
  about "Reorder parts below their minimum"
  policy RepairPolicy
  sheet Parts "Parts" { part: Text, qty: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every day at 08:00

  let all = fetch Parts
  let low = filter all where qty < minimum
  for each i in low up to 3 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $200.00 {
      notify owner "Reorder of {i.part} would cost {cost}, over the $200 limit."
      skip
    }
    order "{i.reorder_qty} x {i.part}" from i.supplier cost cost, ask owner first timeout 12 hours else skip
    log "ordered {i.part}"
  }
}

procedure RepairFollowUpAfterWait {
  about "Contact a new ticket, then follow up again"
  policy RepairPolicy
  sheet Tickets "Tickets" { ticket: Text, customer: Text, email: Email, opened: Date, device: Text, status: Text, password: Text private }
  trigger when new row r in Tickets

  let first = draft email to r.email subject "Your ticket number": "Hi {r.customer}, thanks for opening a ticket! Your ticket number is {r.ticket}."
  let ok1 = request approval of first from owner timeout 1 day else skip
  send ok1
  wait 3 days
  let all = fetch Tickets
  let now_r = find all where email == r.email else stop "row was removed"
  if now_r.status == "new" {
    notify owner "Ticket {now_r.ticket} is still new by then."
  }
}

