  about "Follow up with pet owners marked overdue"
  policy VetPolicy
  sheet Pets "Pets" { owner: Text, phone: Phone, vaccine_due: Date, status: Text, balance: Money, medical_notes: Text private }
  trigger every wednesday at 18:00

  let all = fetch Pets
